// Real daemon/SDK/WebSocket broker regression. The native bridge is deliberately
// synthetic: this is NOT Electron, packaged desktop, or SSH-route acceptance.
// Build SDK first, then: node --test packages/sdk/scripts/browser-acceptance.mjs
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { test } from 'node:test';
import { createWhipClient, webSocket } from '../dist/index.js';
import { eventually, startFixture } from './fixture.mjs';

// A 4x3 JPEG generated by Go image/jpeg, without a browser/image dependency.
const jpeg = new Uint8Array(Buffer.from('', 'base64'));
const deadline = () => ({ signal: AbortSignal.timeout(15_000) });

test('WebSocket Browser screenshots retain selected-holder/root/agent upload provenance', { timeout: 180_000 }, async t => {
  const fixture = await startFixture();
  const clients = [];
  t.after(async () => { for (const client of clients) client.close(); await fixture.close(); });
  const requests = [];
  const socket = webSocket(fixture.info.endpoint);
  const holder = createWhipClient({
    clientId: crypto.randomUUID(), clientKind: 'human', browserProvider: true, reconnect: false,
    endpoint: async (handlers, signal) => {
      const transport = await socket(handlers, signal);
      return {
        kind: transport.kind, httpEndpoint: transport.httpEndpoint,
        get bufferedAmount() { return transport.bufferedAmount; },
        send(data) { requests.push(JSON.parse(data)); transport.send(data); },
        close() { transport.close(); },
      };
    },
  });
  clients.push(holder);
  await holder.connect();
  assert.equal(holder.transportKind, 'websocket');
  async function root() {
    const result = await holder.submit('session.create', {
      kind: 'tool_host', cwd: fixture.directory, model: '', provider: '', permission_mode: 'prompt',
    }).result(deadline());
    assert.equal(result.status, 'succeeded', JSON.stringify(result));
    return result.result.root_id;
  }
  const rootId = await root();
  const foreignRoot = await root();
  const nativeCommands = [];
  const releases = [];
  const errors = [];
  const bridge = {
    async select(input) { assert.equal(input.offer.root_id, rootId); },
    async dispatch(command) {
      nativeCommands.push(command);
      assert.equal(command.root_id, rootId);
      assert.equal(command.agent_id, rootId);
      const result = {
        command_id: command.command_id, root_id: command.root_id, provider_epoch: command.provider_epoch,
        attachment_generation: command.scope.attachment_generation, document_revision: 'doc-1', result: {},
      };
      if (command.kind === 'cdp') {
        const { method } = command.arguments;
        if (method === 'Page.captureScreenshot') return { ...result, screenshotBytes: jpeg };
        if (method === 'Page.getLayoutMetrics') result.result = { cssLayoutViewport: { pageX: 0, pageY: 0, clientWidth: 4, clientHeight: 3 } };
        if (method === 'Runtime.evaluate') result.result = { result: { type: 'string', value: JSON.stringify({ url: 'https://93.184.216.34/', title: 'synthetic native JPEG' }) } };
      }
      return result;
    },
    cancel() {},
    async release(input) { releases.push(input); },
    onEvent() { return () => {}; },
  };
  const selection = await holder.browser.select({
    root_id: rootId, version: 1, desktop_id: 'sdk-regression-desktop', window_id: 'sdk-regression-window',
    offer_revision: 'sdk-regression-offer', create_profile_id: 'sdk-regression-profile', offered_tabs: [], offered_preview_hosts: [],
  }, bridge, { onError: error => errors.push(error), timeoutMs: 10_000 });
  t.after(async () => { if (selection.active) await selection.release(); });

  async function tool(name, args, approve = false) {
    const command = holder.submit('tool.call', { tool: name, arguments: args }, { rootId });
    await command.accepted(deadline());
    if (approve) {
      const permission = await eventually(async () => (await holder.session(rootId).snapshot()).permissions?.find(item => item.status === 'pending'));
      assert.match(permission.command, /Agent control/);
      assert.equal(nativeCommands.length, 0, 'native work must wait for consent');
      await holder.permissions.decide({ root_id: rootId, permission_id: permission.id, allow: true }, deadline());
    }
    let result;
    try { result = await command.result(deadline()); } catch (cause) {
      throw new Error(`${name} failed to settle; native=${JSON.stringify(nativeCommands.map(command => command.kind + ':' + (command.arguments?.method ?? '')))}; errors=${JSON.stringify(errors.map(error => error.message))}; requests=${JSON.stringify(requests.slice(-15).map(request => request.method))}`, { cause });
    }
    assert.equal(result.status, 'succeeded', JSON.stringify(result));
    const value = JSON.parse(result.result.text);
    assert.equal(value.error, undefined, JSON.stringify(value));
    return value;
  }
  // The synthetic bridge never connects to this public literal; it avoids DNS
  // in the real helper's post-run URL safety check (unresolvable .test is denied).
  const opened = await tool('browser_open', { url: 'https://93.184.216.34/' }, true);
  assert.ok(opened.attachment_id);
  const fetch = globalThis.fetch;
  let httpCalls = 0;
  globalThis.fetch = async () => { httpCalls++; throw new Error('Browser screenshot must not use HTTP or fallback'); };
  let screenshot;
  try {
    screenshot = await tool('browser_run', { attachment_id: opened.attachment_id, code: 'screenshot()' });
  } finally { globalThis.fetch = fetch; }
  assert.equal(httpCalls, 0);
  assert.deepEqual(errors, []);
  assert.equal(selection.active, true, 'broker accepted screenshot without revoking holder');
  assert.equal(screenshot.media.length, 1);
  const upload = requests.filter(request => request.method.startsWith('upload.'));
  assert.deepEqual(upload.map(request => request.method), ['upload.begin', 'upload.chunk', 'upload.finish']);
  const begin = upload[0].params;
  assert.equal(begin.root_id, rootId);
  assert.equal(begin.agent_id, rootId);
  assert.equal(begin.media_type, 'image/jpeg');
  assert.equal(begin.size, String(jpeg.byteLength));
  assert.equal(begin.expected_digest, createHash('sha256').update(jpeg).digest('hex'));
  assert.deepEqual(new Uint8Array(Buffer.from(upload[1].params.data, 'base64')), jpeg);
  assert.equal(upload[1].params.upload_id, begin.upload_id);
  assert.equal(upload[2].params.upload_id, begin.upload_id);
  const screenshotCommand = nativeCommands.find(command => command.arguments?.method === 'Page.captureScreenshot');
  assert.ok(screenshotCommand);
  const result = requests.find(request => request.method === 'browser.command.result' && request.params.command_id === screenshotCommand.command_id);
  assert.ok(result.params.screenshot.reference_id);
  assert.equal(result.params.screenshot.digest, begin.expected_digest);
  assert.equal(Object.hasOwn(result.params, 'screenshotBytes'), false);
  assert.equal(Object.hasOwn(result.params.result ?? {}, 'data'), false);
  assert.equal(requests.filter(request => request.method === 'browser.command.result' && request.params.command_id === screenshotCommand.command_id).length, 1);
  const content = await holder.call('content.read', { root_id: rootId, agent_id: rootId, reference_id: screenshot.media[0], offset: '0', limit: jpeg.byteLength }, deadline());
  assert.deepEqual(new Uint8Array(Buffer.from(content.data, 'base64')), jpeg);
  assert.equal(content.content.media_type, 'image/jpeg');
  await assert.rejects(holder.call('content.read', { root_id: foreignRoot, agent_id: foreignRoot, reference_id: screenshot.media[0], offset: '0', limit: jpeg.byteLength }, deadline()));
  await tool('browser_detach', { attachment_id: opened.attachment_id });
  await selection.release();
  assert.equal(selection.active, false);
  assert.ok(releases.some(item => item.rootId === rootId && item.providerEpoch === selection.provider.provider_epoch));
  t.diagnostic(JSON.stringify({ transport: 'real WebSocket', broker: 'production', native: 'synthetic', bytes: jpeg.byteLength, http_calls: httpCalls, upload_rpcs: upload.length, cross_root_read: 'denied', screenshot_replay: false }));
});
